194	impl Latch for SpinLatch<'_> {
195	    #[inline]
196	    unsafe fn set(this: *const Self) {
197	        unsafe {
198	            let registry: &Registry = if (*this).cross {
199	                // Ensure the registry stays alive while we notify it.
200	                // Otherwise, it would be possible that we set the spin
201	                // latch and the other thread sees it and exits, causing
202	                // the registry to be deallocated, all before we get a
203	                // chance to invoke `registry.notify_worker_latch_is_set`.
204	                &Arc::clone((*this).registry)
205	            } else {
206	                // If this is not a "cross-registry" spin-latch, then the
207	                // thread which is performing `set` is itself ensuring
208	                // that the registry stays alive. However, that doesn't
209	                // include this *particular* `Arc` handle if the waiting
210	                // thread then exits, so we must completely dereference it.
211	                (*this).registry
212	            };
213	            let target_worker_index = (*this).target_worker_index;
214	
215	            // NOTE: Once we `set`, the target may proceed and invalidate `this`!
216	            if CoreLatch::set(&(*this).core_latch) {
217	                // Subtle: at this point, we can no longer read from
218	                // `self`, because the thread owning this spin latch may
219	                // have awoken and deallocated the latch. Therefore, we
220	                // only use fields whose values we already read.
221	                registry.notify_worker_latch_is_set(target_worker_index);
