591	    /// Signals that the thread pool which owns this registry has been
592	    /// dropped. The worker threads will gradually terminate, once any
593	    /// extant work is completed.
594	    pub(super) fn terminate(&self) {
595	        if self.terminate_count.fetch_sub(1, Ordering::AcqRel) == 1 {
596	            for (i, thread_info) in self.thread_infos.iter().enumerate() {
597	                unsafe { OnceLatch::set_and_tickle_one(&thread_info.terminate, self, i) };
598	            }
599	        }
600	    }
